    public var roles: [String: Bool]
    /// Opaque encoded chunks, keyed `chunk-{from}-{seq:020}`.
    ///
    /// `from` is in the key on purpose. Without it, two senders that minted the
    /// same seq collided on one key and last-writer-wins destroyed one of them —
    /// the defect behind the one-directional video in `retro/review.md`. The seq
    /// is zero-padded so key order is seq order and a sender's window is one
    /// range read.
    ///
    /// `Moderated`: a chunk is owned by its sender's account, so nobody else can
    /// overwrite or delete it, and the moderators (the creator) may reap a
    /// departed sender's buffer. Readers still check each chunk's owner against
    /// the sender's member row, because anyone can INSERT a new key under
    /// someone else's `from`.
    public var chunks: [String: MediaChunk]
    /// Per-sender sequence / keyframe / pruning state, keyed by device and owned
    /// by its sender. See [`ChunkCursor`] for why this is per sender and merges
    /// by `max`; `Authored` is what stops another member from pushing someone
    /// else's `max` to `u64::MAX` and freezing their stream for good.
    public var chunkCursors: [String: ChunkCursor]

    public init(streamName: String, initialName: String, members: [String: Member], fragments: [String: Fragment], nextSeq: UInt64, roles: [String: Bool], chunks: [String: MediaChunk], chunkCursors: [String: ChunkCursor]) {
        self.streamName = streamName
        self.initialName = initialName
        self.members = members
        self.fragments = fragments
        self.nextSeq = nextSeq
        self.roles = roles
        self.chunks = chunks
        self.chunkCursors = chunkCursors
    }

    enum CodingKeys: String, CodingKey {
        case streamName = "stream_name"
        case initialName = "initial_name"
        case members
        case fragments
        case nextSeq = "next_seq"
        case roles
        case chunks
        case chunkCursors = "chunk_cursors"
    }
}

/// One sender's read cursor, both as input to `get_chunks` and as output from
/// `keyframe_cursors`.
///
/// Seq spaces are per sender now, so a single global "after_seq" is meaningless:
/// seq 40 from Alice and seq 40 from Bob are unrelated positions in unrelated
/// bitstreams.
public struct SenderCursor: Codable, Sendable, Equatable {
    public var from: String
    public var afterSeq: UInt64

    public init(from: String, afterSeq: UInt64) {
        self.from = from
        self.afterSeq = afterSeq
    }
}

/// Per-sender slice of `get_live_stats`.
public struct SenderStats: Codable, Sendable, Equatable {
    public var from: String
    public var nextSeq: UInt64
    public var oldestLive: UInt64
    public var lastKeyframe: UInt64
    public var newestAt: UInt64
    public var pruned: UInt64
    public var liveChunks: UInt32
    public var liveBytes: UInt64

    public init(from: String, nextSeq: UInt64, oldestLive: UInt64, lastKeyframe: UInt64, newestAt: UInt64, pruned: UInt64, liveChunks: UInt32, liveBytes: UInt64) {
        self.from = from
        self.nextSeq = nextSeq
        self.oldestLive = oldestLive
        self.lastKeyframe = lastKeyframe
        self.newestAt = newestAt
        self.pruned = pruned
        self.liveChunks = liveChunks
        self.liveBytes = liveBytes
    }
}

/// Instrumentation snapshot (§4 metrics — the deliverable). Cheap counters a
/// load generator / e2e can poll to chart the failure curve.
public struct StreamStats: Codable, Sendable, Equatable {
    public var name: String
    public var memberCount: UInt32
    /// Fragments (chunks) currently live in state.
    public var liveFragments: UInt32
    /// Highest frame seq ever allocated (monotone; also == total frames sent).
    public var nextSeq: UInt64
    /// Lowest frame seq still live (frames below this were pruned → tombstones).
    public var oldestLiveSeq: UInt64
    /// How many frames have been pruned (each pruned fragment is a tombstone, C3).
    public var prunedFrames: UInt64

    public init(name: String, memberCount: UInt32, liveFragments: UInt32, nextSeq: UInt64, oldestLiveSeq: UInt64, prunedFrames: UInt64) {
        self.name = name
        self.memberCount = memberCount
        self.liveFragments = liveFragments
        self.nextSeq = nextSeq
        self.oldestLiveSeq = oldestLiveSeq
        self.prunedFrames = prunedFrames
    }
}
